const C=window.SS2Content,P=window.SS2Packs,Meta=window.SS2Presentation,Core=window.SS2Core,Store=window.SS2Storage,Q=window.SS2QualityCandidates,portraits={},imageBackground=new Image;
let state=null,selected=-1,renderer=null,loadBlocked=false,warning='',toastUntil=0,playIndex=0,playAge=0,paused=false,lastFrame=0,lastDraw=0,clock=0,currentEvent=null,previousTeams=null,ghosts=[],deathTransition=null;
const DEATH_SECONDS=.7;
const Feedback=window.SS2BattleFeedback;let feedbackEnabled=true,lessMotion=false,feedbackPrevious=null;
function feedback(){return Feedback?.describe(currentEvent,feedbackPrevious,name)||null;}
function feedbackRole(uid){return feedbackEnabled?feedback()?.marks.find(m=>m.uid===uid)?.role||'':'';}
function feedbackHTML(e){const f=Feedback?.describe(e,feedbackPrevious,name);return f?'<img src="'+f.icon+'" alt="" width="24" height="24"><span>'+esc(f.summary)+'</span>':'';}
function renderFeedback(){const box=$('#pc-battle-event');box.hidden=isMobile()||state?.phase!=='battle'||!feedbackEnabled||!currentEvent;if(!box.hidden)box.innerHTML=feedbackHTML(currentEvent);if(state?.phase==='battle'&&isMobile()){$('#m-battle-event').innerHTML=feedbackEnabled?feedbackHTML(currentEvent):'提示特效已关闭；可打开设置恢复，完整过程保留在战报。';}}
function drawFeedback(context,teams,mobile){const f=feedback();if(!feedbackEnabled||!f||state.phase!=='battle'||deathTransition)return;context.save();for(const mark of f.marks){const i=teams[mark.side]?.findIndex(u=>u.uid===mark.uid);if(i<0||i===undefined)continue;const p=mobile?mobilePosition(i,mark.side):position(i,mark.side,true);context.strokeStyle=mark.role==='source'?'#ffe29a':f.kind==='damage'||f.kind==='debuff'?'#a13432':'#317e70';context.lineWidth=mobile?4:3;context.setLineDash(mark.role==='source'?[]:[6,4]);context.beginPath();context.ellipse(p.x,p.y+5,mobile?39:42,10,0,0,Math.PI*2);context.stroke();context.setLineDash([]);context.font='bold '+(mobile?20:15)+'px Microsoft YaHei';context.textAlign='center';context.fillStyle='#fff9e9';context.strokeStyle='#163c36';context.lineWidth=4;const text=mark.caption;const y=p.y-(mobile?145:135)-(lessMotion||reduced?0:Math.min(playAge,.5)*8);context.strokeText(text,p.x,y);context.fillText(text,p.x,y);}context.restore();}

let activeAssetPack=null,assetsBusy=false;
const actorIndex=Object.fromEntries(Object.entries(SS2_ACTORS));
