 if(!$('#result-banner').hidden){const last=state.history.at(-1),winner=state.battle?.winner||last?.winner;let title=state.phase==='over'?(state.wins>=10?'十战扬名':'再整旗鼓'):winner==='player'?'此战告捷':winner==='draw'?'势均力敌':'暂失一阵';$('#result-banner').innerHTML=`<h2>${title}</h2><p>${state.wins} 胜 · 剩余 ${state.lives} 生命</p><p>${state.phase==='over'?'本局已保存。再开一局，试试另一种构筑。':'本回合已结算。回到营地，继续调整你的队伍。'}</p>${state.phase==='over'?'<button class="primary" data-ui="restart">再开一局</button>':''}`;}
  $('#team').innerHTML=Array.from({length:5},(_,i)=>{const u=state.team[i];return `<button class="team-slot ${u?'filled':''} ${selected===i?'selected':''}" data-slot="${i}" aria-pressed="${selected===i}" ${u&&shopping?'draggable="true"':''} aria-label="${u?'选择 '+esc(name(u))+'，阵位'+(i+1):'空阵位'+(i+1)}"><span class="slot-number">${i===0?'前排':i+1}</span>${u?`<span class="pc-team-portrait">${headHTML(asset(u),name(u))}</span><span class="slot-copy"><strong>${esc(name(u))}</strong><small>Lv.${u.level} · ${u.level===3?'满级':'经验 '+u.xp+'/'+(u.level===1?2:5)}${u.food?' '+equippedFood(u.food):''}</small><span class="stats">${stats(u)}</span></span>`:'<span class="empty">+ 空阵位</span>'}</button>`;}).join('');
