function position(index,side,inBattle){return inBattle?{x:side===0?625-index*122:775+index*122,y:270,scale:.64}:{x:1130-index*215,y:265,scale:.92};}
function draw(now,dt){
 ctx.clearRect(0,0,1400,330);if(imageBackground.complete&&imageBackground.naturalWidth)ctx.drawImage(imageBackground,0,-95,1400,520);else{ctx.fillStyle='#d4e9ec';ctx.fillRect(0,0,1400,330);}
 const battle=state.phase==='battle',teams=stageTeams();
 for(let side=0;side<2;side++)for(let i=teams[side].length-1;i>=0;i--){const u=teams[side][i];if(deathTransition&&ghosts.some(g=>g.unit.uid===u.uid))continue;const pos=position(i,side,battle),id=asset(u);if(!SS2_ACTORS[id]){setWarning('缺少角色实际资源：'+id);continue;}
  ctx.fillStyle=side===0?'#25483d55':'#713a4055';ctx.beginPath();ctx.ellipse(pos.x,pos.y+4,48*pos.scale,9*pos.scale,0,0,Math.PI*2);ctx.fill();let action='ready',age=clock%2;
  if(battle&&currentEvent){if(currentEvent.type==='attack'&&(u.uid===currentEvent.uid||u.uid===currentEvent.sourceUid||u.uid===currentEvent.targetUid||i===0)){action='attack';age=playAge;}if(currentEvent.type==='damage'&&u.uid===(currentEvent.targetUid||currentEvent.uid)){action='hit';age=playAge;}if(u.health<=0){action='hit';age=.62;}}
  const duration=SS2_ACTORS[id].animations[action].duration,t=action==='ready'?age%duration:Math.min(duration,age/.62*duration);renderer.draw(ctx,id,action,t,pos.x,pos.y,pos.scale,side===1);
  ctx.textAlign='center';ctx.fillStyle='#fdf8e7';ctx.strokeStyle='#142d38';ctx.lineWidth=4;ctx.font='bold 14px Microsoft YaHei';let label=`${name(u)}${u.transformed?' · 变身':''}　${u.attack}/${Math.max(0,u.health)}`;ctx.strokeText(label,pos.x,307);ctx.fillText(label,pos.x,307);
 }
 for(const g of ghosts){const id=asset(g.unit);if(!SS2_ACTORS[id])continue;const progress=Math.min(1,deathTransition.age/DEATH_SECONDS);ctx.save();ctx.globalAlpha=1-progress;renderer.draw(ctx,id,'dead',SS2_ACTORS[id].animations.dead.duration*progress,g.pos.x,g.pos.y,g.pos.scale,g.side===1);ctx.restore();}
 if(deathTransition&&deathTransition.age>=DEATH_SECONDS)deathTransition.finalPoseDrawn=true;
 if(battle&&!deathTransition&&currentEvent?.amount){ctx.font='bold 26px Georgia';ctx.textAlign='center';ctx.fillStyle=currentEvent.type==='buff'?'#e9d185':'#fff0e5';ctx.strokeStyle='#713a40';ctx.lineWidth=3;let side=currentEvent.side??1,index=teams[side]?.findIndex(u=>u.uid===(currentEvent.targetUid||currentEvent.uid));const pos=position(Math.max(0,index),side,true);ctx.strokeText(String(currentEvent.amount),pos.x,pos.y-100-playAge*20);ctx.fillText(String(currentEvent.amount),pos.x,pos.y-100-playAge*20);}
 drawFeedback(ctx,teams,false);
}
function presentEvent(e){feedbackPrevious=previousTeams;playIndex++;previousTeams=e.teams;currentEvent=e;playAge=0;$('#battle-progress').textContent=`战报 ${playIndex} / ${state.battle.events.length}`;const types={attack:'交锋',damage:'受伤',faint:'阵亡',summon:'召唤',buff:'强化',start:'开战',end:'战果',ability:'技能',shield:'护盾',transform:'变身',copy:'借技'};const label=e.message||`${types[e.type]||e.type}${e.amount?'　'+e.amount:''}`;const log=$('#battle-log');log.textContent+=(log.textContent?'\n':'')+label;log.scrollTop=log.scrollHeight;if(isMobile()){renderMobileBattleStats();$('#m-battle-event').textContent=eventSummary(e);}else renderPCBattle();renderFeedback();}
function advanceEvent(){const events=state.battle.events;if(playIndex>=events.length){act({type:'FINISH_BATTLE'});return;}const e=events[playIndex];ghosts=[];if(previousTeams&&e.teams){for(let side=0;side<2;side++)for(let i=0;i<previousTeams[side].length;i++){const u=previousTeams[side][i];if(u.health<=0&&!e.teams[side].some(x=>x.uid===u.uid))ghosts.push({unit:u,pos:position(i,side,true),side,index:i});}}if(ghosts.length){deathTransition={event:e,age:0,finalPoseDrawn:false};return;}presentEvent(e);}
function loop(now){const dt=Math.min(.1,Math.max(0,(now-lastFrame)/1000||0));lastFrame=now;clock+=dt;if(toastUntil&&now>toastUntil){$('#toast').classList.remove('visible');toastUntil=0;}
 if(state?.phase==='battle'&&modelsReady&&!battleGate.busy&&!paused){const speed=Number($('#speed').value);if(deathTransition){if(deathTransition.finalPoseDrawn){const e=deathTransition.event;deathTransition=null;ghosts=[];presentEvent(e);}else deathTransition.age=Math.min(DEATH_SECONDS,deathTransition.age+dt*speed);}else{playAge+=dt*speed;if(!currentEvent||playAge>=.65)advanceEvent();}}
 if(state&&renderer&&now-lastDraw>(reduced?120:40)){if(isMobile())drawMobile(now,dt);else draw(now,dt);lastDraw=now;}requestAnimationFrame(loop);}
let modalReturn=null;
function openModal(html){if(state?.phase==='battle'&&!$('#modal').open){modalPause=paused;paused=true;}if(!$('#modal').open)modalReturn=document.activeElement;$('#modal-content').onclick=null;$('#modal-content').innerHTML=html;const heading=$('#modal-content').querySelector('h2');if(heading){heading.id='modal-title';heading.setAttribute('tabindex','-1');}if(!$('#modal').open)$('#modal').showModal();mountPortraits();heading?.focus({preventScroll:true});$('#modal').scrollTop=0;}
