function showSavedRuns(){let rows;try{rows=Store.listRuns();}catch(e){toast('保留局未能打开：'+e.message);return;}openModal('<h2 class="modal-title">保留局</h2><p class="muted">仅保存在这台设备。恢复前会保留当前有进度的局面。</p>'+rows.map((x,i)=>'<article class="saved-run"><h3>'+esc(packName(x.packId))+'</h3><p>第 '+x.turn+' 回合</p><div><button class="primary" data-resume-run="'+i+'">恢复此局</button><button data-export-run="'+i+'">导出</button><button data-remove-run="'+i+'">移除</button></div></article>').join('')+(!rows.length?'<div class="empty-state"><h3>暂时没有保留局</h3><p>换主题或导入其他存档前，有进度的局面会留在这里。</p></div>':'')+'<p class="muted">最多保留十局。满时会提醒你先导出并移除一局。</p>');$('#modal-content').onclick=async e=>{const resume=e.target.closest('[data-resume-run]'),exp=e.target.closest('[data-export-run]'),remove=e.target.closest('[data-remove-run]');try{if(exp){const x=rows[Number(exp.dataset.exportRun)];downloadText(x.text,'ss2-retained-'+x.seed+'-turn'+x.turn+'.json');}if(resume){const x=rows[Number(resume.dataset.resumeRun)],next=Store.importSave(x.text);confirmRunSwitch(next,'恢复保留局');}if(remove){const x=rows[Number(remove.dataset.removeRun)];openModal('<h2 class="modal-title">移除这份保留局？</h2><p>'+esc(packName(x.packId))+' · 第 '+x.turn+' 回合。移除后无法从这里恢复，可先导出文件保留。</p><button id="export-before-remove">先导出</button><button class="danger" id="confirm-remove">确认移除</button>');$('#export-before-remove').onclick=()=>downloadText(x.text,'ss2-retained-'+x.seed+'.json');$('#confirm-remove').onclick=()=>{Store.removeRun(x.id);showSavedRuns();};}}catch(err){toast(err.message);}};}
