function upgradeGroupKey(o){return original()&&typeof o?.rewardGroup==='string'&&o.rewardGroup?o.rewardGroup:null;}
function upgradeGroups(){const groups=new Map();state.shop.units.forEach((o,index)=>{const key=upgradeGroupKey(o);if(key){if(!groups.has(key))groups.set(key,[]);groups.get(key).push({o,index});}});return [...groups].map(([key,rows],i)=>({key,rows,number:i+1}));}
function upgradeOfferCopy(o){const key=upgradeGroupKey(o),g=key&&upgradeGroups().find(g=>g.key===key);return g?'本次升级 · 第'+g.number+'组 · '+(g.rows.length===1?'仅剩此候选；招募花费3金。':(g.rows.length===2?'二选一':g.rows.length+'项中选一')+'；招募花费3金，选中后同组其余候选撤下。'):'';}
