const ordinary=indices.filter(i=>state.shop.units[i]&&!upgradeGroupKey(state.shop.units[i])).map(i=>renderCard(state.shop.units[i],i)).join('');
const grouped=groups.filter(g=>g.rows.some(r=>include.has(r.index))).map(g=>{const title='升级进阶招募 · '+(g.rows.length===1?'仅剩一位':g.rows.length===2?'二选一':g.rows.length+'项中选一'),id='upgrade-'+(mobile?'mobile':'pc')+'-'+g.number;return '<section class="upgrade-choice" role="group" aria-labelledby="'+id+'"><h4 id="'+id+'">'+esc(title)+'</h4><p>本次升级 · 第'+g.number+'组。'+(g.rows.length===1?'此候选招募花费3金。':'每位3金；招募一位后，同组其余候选撤下。')+'</p><div class="upgrade-cards">'+g.rows.filter(r=>include.has(r.index)).map(r=>renderCard(r.o,r.index)).join('')+'</div><small>未冻结候选在刷新或下一回合撤下，冻结的保留。</small></section>';}).join('');
