 if(mChoice&&(mChoice.kind==='team'?!hasUid(mChoice.uid):!state||mChoice.token!==selectionToken(mChoice.kind,mChoice.index)||!state.shop[mChoice.kind]?.[mChoice.index]))mChoice=null;
