const actorPromises=new Map();
async function prepareActorSet(ids,progress,valid=()=>true){let done=0;for(const id of ids){if(!valid())throw Error('已取消准备');const info=SS2_ACTORS[id]||actorIndex[id];if(!info)throw Error('缺少参战人物资源：'+id);if(!SS2_ACTORS[id]?.atlas&&info.lazyDataPath){if(!/^objects\/[a-f0-9]{64}\.js$/.test(info.lazyDataPath))throw Error('人物动作路径无效');if(!actorPromises.has(id))actorPromises.set(id,new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=info.lazyDataPath;script.onload=()=>{script.remove();if(!SS2_ACTORS[id]?.atlas){actorPromises.delete(id);reject(Error('人物动作内容不完整'));}else resolve();};script.onerror=()=>{script.remove();actorPromises.delete(id);reject(Error('人物动作未能载入，请重试'));};document.head.appendChild(script);}));try{await actorPromises.get(id);}finally{actorPromises.delete(id);}}progress({done:++done,total:ids.length});}if(!valid())throw Error('已取消准备');const data=Object.fromEntries(ids.map(id=>[id,SS2_ACTORS[id]])),nextRenderer=await new SS2Renderer(data).load();return {renderer:nextRenderer,ids:new Set(ids),portraits:{},packId:'battle'};}
const battleGate=Mobile.createGate({getState:()=>state,getRevision:()=>revision,compute:(base,command)=>{if(command.type==='RESUME_VISUAL')return base;if(command.type==='ADOPT_RUN'){Core.validateState(command.next);return command.next;}return Core.act(base,command);},prepare:async(next,progress,valid)=>{if(next.phase==='battle')return prepareActorSet(Mobile.battleIds(next,id=>C.BY_ID[id]||unitDef(id)),progress,valid);return isMobile()?null:loadPackAssets(next.packId);},commit:(next,bundle,command)=>{if(command.type==='ADOPT_RUN'&&!retainCurrent())throw Error('当前局未能保留，请先导出并处理保留局。');if(next!==state){Mobile.persist(webState(next),Store);state=next;revision++;selected=-1;loadBlocked=false;resetPlayback();clearMobileChoice();}activateAssets(bundle);if(command.type==='BATTLE')SS2Lineups.record(state);modelsReady=next.phase==='battle'&&!!bundle;resumePending=false;setWarning('');$('#save-status').textContent='已保存到本机';render();if(command.type==='ADOPT_RUN')$('#modal').close();},report:status=>{if(status.state==='settled'){if(state)render();return;}const loading=status.state==='loading',failed=status.state==='failed';$('#m-loading').hidden=!loading&&!failed;$('#m-loading').dataset.state=status.state;if(loading){$('#m-load-title').textContent=resumePending?'恢复战斗画面…':'正在准备本局…';$('#m-load-message').textContent=status.progress?'人物 '+status.progress.done+' / '+status.progress.total:'准备完成并保存成功后才会切换。';}if(failed){$('#m-load-title').textContent='准备未完成';$('#m-load-message').textContent=status.error.message+'。局面未切换，可重试或返回。';setWarning(status.error.message);}if(status.state==='done'){$('#m-load-message').textContent='';setWarning('');}$('#m-load-retry').hidden=!failed;$('#m-load-cancel').textContent=resumePending?'返回（保留战斗存档）':'取消，保留当前局';if(state)renderMobile();}});
async function startMobileBattle(){if(state.phase!=='shop'||battleGate.busy||loadBlocked)return;clearMobileChoice();await battleGate.run({type:'BATTLE'});}
function mobilePosition(index,side){return {x:72+index*144,y:side===0?550:255,scale:.48};}
function drawMobile(){const width=720,height=600;mobileCtx.clearRect(0,0,width,height);if(imageBackground.complete&&imageBackground.naturalWidth)mobileCtx.drawImage(imageBackground,0,0,width,height);else{mobileCtx.fillStyle='#d4e9ec';mobileCtx.fillRect(0,0,width,height);}if(!modelsReady||!renderer)return;const teams=stageTeams();for(let side=0;side<2;side++)for(let i=teams[side].length-1;i>=0;i--){const u=teams[side][i],id=asset(u),pos=mobilePosition(i,side);if(!SS2_ACTORS[id]?.animations||deathTransition&&ghosts.some(g=>g.unit.uid===u.uid))continue;let action='ready',age=clock%2;if(currentEvent){if(currentEvent.type==='attack'&&(u.uid===currentEvent.uid||u.uid===currentEvent.sourceUid||u.uid===currentEvent.targetUid||i===0)){action='attack';age=playAge;}if(currentEvent.type==='damage'&&u.uid===(currentEvent.targetUid||currentEvent.uid)){action='hit';age=playAge;}if(u.health<=0){action='hit';age=.62;}}const animation=SS2_ACTORS[id].animations[action]||SS2_ACTORS[id].animations.ready,duration=animation.duration,t=action==='ready'?age%duration:Math.min(duration,age/.62*duration);renderer.draw(mobileCtx,id,action,t,pos.x,pos.y,pos.scale,side===1);}
for(const g of ghosts){const id=asset(g.unit);if(!SS2_ACTORS[id]?.animations?.dead)continue;const progress=Math.min(1,deathTransition.age/DEATH_SECONDS),pos=mobilePosition(g.index,g.side);mobileCtx.save();mobileCtx.globalAlpha=1-progress;renderer.draw(mobileCtx,id,'dead',SS2_ACTORS[id].animations.dead.duration*progress,pos.x,pos.y,pos.scale,g.side===1);mobileCtx.restore();}if(deathTransition&&deathTransition.age>=DEATH_SECONDS)deathTransition.finalPoseDrawn=true;drawFeedback(mobileCtx,teams,true);}
