function configureViewport(){document.body.classList.toggle('mobile-game',isMobile());if(!state)return;render();if(state.phase==='battle'&&!modelsReady&&!battleGate.busy){resumePending=true;battleGate.run({type:'RESUME_VISUAL'});}else if(!isMobile()&&state.phase!=='battle'&&!battleGate.busy){const base=state,epoch=++assetEpoch;loadPackAssets(state.packId).then(bundle=>{if(state===base&&epoch===assetEpoch&&!isMobile()){activateAssets(bundle);render();}}).catch(e=>setWarning('人物未准备完成：'+e.message+'。可切回手机布局继续整备，或重新载入。'));}}
