function skillHTML(u,full=false,food=false){const v=food?(View.food?.(u)||{description:u.description}):View.unit(u,state),l=v.layers||v;let body=l.effect?['trigger','requirements','effect'].map(k=>l[k]?'<p class="skill-'+k+'">'+esc(Array.isArray(l[k])?l[k].join('；'):l[k])+'</p>':'').join(''):'<p>'+esc(v.description||description(u))+'</p>';if(l.badges?.length)body+='<p class="skill-badges">'+l.badges.map(x=>'<span>'+esc(typeof x==='string'?x:x.text||x.name||'')+'</span>').join('')+'</p>';if(!food&&v.quotaText)body+='<p class="skill-quota">'+esc(v.quotaText)+'</p>';if(full){const notes=l.notes||v.notes,glossary=l.glossary||v.glossary;body+=(Array.isArray(notes)?notes:notes?[notes]:[]).map(x=>'<p class="rule-note">'+esc(x)+'</p>').join('');if(glossary?.length)body+='<details class="skill-glossary"><summary>术语说明</summary>'+glossary.map(x=>'<p><b>'+esc(x.name)+'</b> '+esc(x.text)+'</p>').join('')+'</details>';}return '<div class="skill-layers">'+body+'</div>';}
function equipmentHTML(u){const e=View.unit(u,state).equipment;return e?'<p class="equipment-copy '+(e.spent?'spent':'')+'">'+(e.icon?'<img src="'+esc(e.icon)+'" alt="" width="24" height="24">':'')+esc(e.name)+(e.spent?' · 已消耗':'')+'：'+esc(e.description)+'</p>':'';}
function renderPCBattle(){const box=$('#pc-battle-roster');box.hidden=isMobile()||state.phase!=='battle';if(box.hidden)return;box.innerHTML=stageTeams().map((team,side)=>'<section><h3>'+(side===0?'我军（前排在右）':'敌军')+'</h3><div class="pc-live-team" data-side="'+side+'">'+team.map((u,i)=>'<button data-live-uid="'+esc(u.uid)+'" data-live-side="'+side+'" data-fx="'+feedbackRole(u.uid)+'">'+headHTML(asset(u),name(u))+'<b>'+esc(name(u))+'</b><span>攻 '+u.attack+' / 血 '+Math.max(0,u.health)+' · Lv.'+u.level+'</span><small>'+esc(View.unit(u,state).quotaText)+'</small>'+(u.food?equippedFood(u.food):'')+'</button>').join('')+'</div></section>').join('');enhanceHeads();}
function copyHTML(u,team=state.team){const p=View.copyPreview(state,u,team);return p?'<div class="copy-preview"><b>当前借技对象</b><p>'+esc(p.ok?p.donorName+'：'+p.description:p.reason)+'</p>'+(p.remaining===null||p.remaining===undefined?'':'<p>该技能剩余 '+p.remaining+' 次</p>')+(p.note?'<p>'+esc(p.note)+'</p>':'')+'</div>':'';}
function detail(id,food,instance,team,shopOffer){const d=food?foodDef(id):unitDef(id)||C.BY_ID[id],u=instance||d;if(!u){toast('这项内容不在当前图鉴中');return;}const v=food?{name:d.name}:View.unit(u,state);openModal('<h2 class="modal-title">'+esc(v.name)+'</h2><div class="detail-hero">'+(food?'<span class="food-symbol">'+foodIcon(d)+'</span>':headHTML(asset(u),v.name))+'<div>'+(food?foodLabels(d):labels(d||u))+(food?'':'<p class="detail-stats">攻 '+effectiveAttack(u)+'　血 '+effectiveHealth(u)+' · Lv.'+(u.level||1)+'</p><p>'+esc(v.xpText)+'</p>'+((u.tempAttack||u.tempHealth)?'<p class="temporary-stats">基础攻 '+u.attack+' / 血 '+Math.max(0,u.health)+'；本回合额外攻 +'+(u.tempAttack||0)+' / 血 +'+(u.tempHealth||0)+'（下回合清除）</p>':''))+'</div></div>'+upgradeOfferHTML(shopOffer)+skillHTML(u,true,food)+(food?'':equipmentHTML(u)+copyHTML(u,team))+(food?'<div class="rule-note"><p>'+esc(scopeCopy(d))+'</p><p>'+(d.kind==='equipment'?'每人一个装备槽。购买会替换目标的当前装备；无目标时先列出旧装备和费用。':'不占装备槽，期限以此军需说明为准。')+'</p></div>':'<p class="rule-note">累计经验2 / 5升至二 / 三级；最高三级。详情展示当前等级的实际技能。</p>')+'<p class="muted">查看详情不会购买、出售或改变战斗结果。</p><button data-back-catalog>查看图鉴</button>');}
function scopeCopy(d){const s=Mobile.scope(d);return s==='single'?'指定一名合法友军；点击购买即施用，没有目标时点选目标即施用。':s==='random'?'由规则随机选取友军；点击购买即生效。':s==='all'?'作用于全部合法友军；点击购买即生效。':s==='shop'?'作用于商店；点击购买即生效，无需选择友军。':'购买后即时生效；无需选择友军。';}
function confirmSale(u){const base=state,rev=revision,quote=View.sale(state,u.uid);if(!quote.ok){toast(quote.reason);return;}openModal('<h2 class="modal-title">出售 '+esc(name(u))+'？</h2><p>本次共获得 '+quote.gold+' 金币（含出售技能和额外价值）。</p>'+skillHTML(u,false)+'<button class="danger" id="confirm-sale">确认出售 · +'+quote.gold+' 金</button><button id="cancel-sale">取消</button>');$('#cancel-sale').onclick=()=>$('#modal').close();$('#confirm-sale').onclick=()=>{if(state!==base||revision!==rev){toast('局面已改变，请重新选择');return;}const slot=state.team.findIndex(x=>x.uid===u.uid);if(slot>=0&&act({type:'SELL',slot})){$('#modal').close();clearMobileChoice();render();}};}
function confirmPurchase(kind,index,expected,mergeUid=null){
if(battleGate.busy||assetsBusy||state.phase!=='shop'||expected!==selectionToken(kind,index)){toast(assetsBusy?'正在载入人物，请稍候再购买':'商品已改变，请重新选择');return false;}
const base=state,rev=revision,offer=state.shop[kind]?.[index];if(!offer)return false;const food=kind==='food',d=food?foodDef(offer.id):View.offer(offer),price=food?foodCost(offer):3,scope=food&&Mobile.scope(d),needTarget=food?scope==='single':!!mergeUid||state.team.length>=5;let committed=false,picking=false;
if(state.gold<price){toast('金币不足，还差 '+(price-state.gold)+' 金');return false;}
function submit(targetUid=null){if(committed||state!==base||revision!==rev||selectionToken(kind,index)!==expected){toast('局面已改变，请重新选择');return false;}const slot=state.team.findIndex(u=>u.uid===targetUid);if(needTarget&&slot<0){toast('目标已离队，请重新选择');return false;}const command={type:food?'FOOD':'BUY',index,token:offer.token};if(slot>=0)command[food?'target':'slot']=slot;
// Historical random/shop foods require an adapter target, not a recipient.
if(food&&scope!=='single'&&original()&&state.team.length)command.target=0;
if(!act(command))return false;committed=true;if(picking)$('#modal').close();clearMobileChoice();render();return true;}
if(!needTarget)return submit();
const candidates=food?state.team:state.team.filter(u=>u.id===offer.id),targets=candidates.map(u=>{let reason='';try{if(!food&&u.level===3)throw Error('已满级');Core.act(base,{type:food?'FOOD':'BUY',index,token:offer.token,...(food?{target:base.team.indexOf(u)}:{slot:base.team.indexOf(u)})});}catch(e){reason=e.message;}return {u,reason};}),valid=targets.filter(x=>!x.reason);
if(mergeUid){if(!valid.some(x=>x.u.uid===mergeUid)){toast('合成目标已失效，请重新选择');return false;}return submit(mergeUid);}
const chosen=food?state.team[selected]:null;if(chosen&&valid.some(x=>x.u.uid===chosen.uid))return submit(chosen.uid);
if(!valid.length){toast(food?'没有合法的施用目标':'队伍已满，没有可合成的同名武将');return false;}
picking=true;openModal('<h2 class="modal-title">'+(food?'选择施用目标':'选择同名合成目标')+' · '+esc(d.name)+'</h2><p>点选目标即'+(food?'施用':'购买并合成')+'，花费 '+price+' 金。</p><div id="purchase-targets" class="target-options">'+targets.map(({u,reason})=>'<button data-purchase-target="'+esc(u.uid)+'" '+(reason?'disabled':'')+'>'+headHTML(asset(u),name(u))+'<span>'+esc(name(u))+' · Lv.'+u.level+'<small>'+esc(reason||(food&&d.kind==='equipment'?(View.unit(u,state).equipment?.name||'空装备槽')+' → '+d.name:View.unit(u,state).xpText))+'</small></span></button>').join('')+'</div><button id="cancel-purchase">取消</button>');
$('#cancel-purchase').onclick=()=>$('#modal').close();$('#purchase-targets').onclick=e=>{const b=e.target.closest('[data-purchase-target]');if(b&&!b.disabled&&valid.some(x=>x.u.uid===b.dataset.purchaseTarget))submit(b.dataset.purchaseTarget);};return false;}
function confirmMerge(fromUid,toUid){const base=state,rev=revision,from=state.team.find(u=>u.uid===fromUid),to=state.team.find(u=>u.uid===toUid);if(!from||!to||from===to||from.id!==to.id||from.level===3||to.level===3)return;openModal('<h2 class="modal-title">确认同名合成</h2><p>'+esc(name(from))+'（阵位'+(state.team.indexOf(from)+1)+'）合成到阵位'+(state.team.indexOf(to)+1)+'的 '+esc(name(to))+'。不花金币；累计经验2 / 5升级。</p><p>目标：'+esc(View.unit(to,state).xpText)+'</p><button class="primary" id="confirm-merge">确认合成</button><button id="cancel-merge">取消</button>');$('#cancel-merge').onclick=()=>$('#modal').close();$('#confirm-merge').onclick=()=>{if(state!==base||revision!==rev)return;const from=state.team.findIndex(u=>u.uid===fromUid),to=state.team.findIndex(u=>u.uid===toUid);if(act({type:'MERGE',from,to})){$('#modal').close();clearMobileChoice();render();}};}

